evaluateRequest(req) {
    this._assertRequestHasHeaders(req);

    // Security-zeroed entries cannot become reusable through max-stale.
    // Keep legitimate public stale responses subject to the original rules.
    if (!this.storable() || this._rescc['no-cache'] ||
        (this._isShared && (this._rescc['proxy-revalidate'] ||
            (this._resHeaders['set-cookie'] && !this._rescc.public && !this._rescc.immutable)))) {
        return this._evaluateRequestMissResult(req);
    }
